// ---------------------------------------------------------------
// Normalize the request coming from Retell.
//
// Retell delivers a Custom Function payload as { "args": {...} } by
// default, or flat if args_at_root is on; n8n wraps the HTTP body in
// `body`. Flatten all of that ONCE so every node downstream can just
// read $json.action, $json.policy_number, and so on.
//
// Also repair the two identifiers speech-to-text is most likely to
// mangle:
//   "pol one oh two three four" / "POL 10234" -> POL-10234
//   "claim 42" / "CLM 42"                     -> CLM-000042
// Doing this server-side means the agent never has to be perfect.
// ---------------------------------------------------------------

const raw = $json.body ?? $json;
const a = raw.args ?? raw;

const str = (v) => (v === undefined || v === null ? '' : String(v).trim());

// Speech-to-text does not always render spoken digits as numerals: a
// caller saying "P O L one zero two three four" can transcribe with
// "one" as a word. Stripping non-digits first would silently drop it
// and turn POL-10234 into POL-0234 -- a valid-looking wrong answer,
// which is worse than an obvious failure. Map number words to digits
// first, whole words only so the "POL" prefix is untouched.
const WORDS = {
  zero: 0, oh: 0, o: 0, nought: 0,
  one: 1, won: 1, two: 2, to: 2, too: 2, three: 3, tree: 3,
  four: 4, for: 4, fore: 4, five: 5, six: 6, sicks: 6,
  seven: 7, eight: 8, ate: 8, nine: 9, niner: 9
};
const digits = (v) =>
  str(v)
    .toLowerCase()
    // Drop the alphabetic prefix FIRST. Callers spell it out -- "P O L
    // one zero two three four" -- and the letter O in POL would
    // otherwise be mapped to the digit zero, yielding POL-010234: a
    // wrong answer that still looks like a policy number, which is far
    // worse than an obvious failure.
    .replace(/\b(p[\s.\-]*o[\s.\-]*l|c[\s.\-]*l[\s.\-]*m|policy|claim|number|dash|hyphen)\b/g, ' ')
    .replace(/\b([a-z]+)\b/g, (w) => (w in WORDS ? String(WORDS[w]) : w))
    .replace(/\D/g, '');

return [{
  json: {
    action: str(a.action).toLowerCase(),
    policy_number: digits(a.policy_number) ? `POL-${digits(a.policy_number)}` : '',
    claim_id: digits(a.claim_id) ? `CLM-${digits(a.claim_id).padStart(6, '0')}` : '',
    holder_name: str(a.holder_name || a.name),
    incident_type: str(a.incident_type),
    incident_date: str(a.incident_date),
    description: str(a.description),
    email: str(a.email).toLowerCase(),
    urgency_hint: str(a.urgency)
  }
}];

// ---------------------------------------------------------------
// Find the policy among the rows read from the Policies tab.
//
// The match happens HERE rather than in the Sheets node's filter,
// because that filter's "Column to match on" is a dropdown populated
// from the sheet at edit time, and an import can leave it empty --
// which fails at runtime as `The column "" could not be found`.
// A .find() in code cannot be dropped by a dropdown.
//
// Every outcome returns HTTP 200 with a `result` string. Retell
// branches on that string with an exact-match equation, so the routing
// is deterministic rather than an LLM interpreting a boolean. An HTTP
// error code would instead make the agent say "something went wrong".
// ---------------------------------------------------------------

const asked = $('Normalize Request').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.policy_number);
const row = rows.find(
  (r) => String(r.policy_number).trim().toUpperCase() === asked.policy_number
);

if (!row) {
  return [{ json: {
    result: 'not_found', valid: false, reason: 'not_found',
    policy_number: asked.policy_number,
    message: `No policy found matching ${asked.policy_number}.`
  }}];
}

// A policy that exists but has lapsed is not valid to claim against.
const validUntil = String(row.valid_until || '').trim();
const expiry = validUntil ? new Date(`${validUntil}T23:59:59Z`) : null;

if (expiry && !isNaN(expiry) && expiry < new Date()) {
  return [{ json: {
    result: 'expired', valid: false, reason: 'expired',
    policy_number: row.policy_number, holder_name: row.holder_name,
    coverage_type: row.coverage_type, valid_until: validUntil,
    message: `Policy ${row.policy_number} expired on ${validUntil}.`
  }}];
}

return [{ json: {
  result: 'valid', valid: true, reason: 'ok',
  policy_number: row.policy_number, holder_name: row.holder_name,
  coverage_type: row.coverage_type, valid_until: validUntil,
  message: `Policy ${row.policy_number} is active and held by ${row.holder_name}.`
}}];

// ---------------------------------------------------------------
// Generate the claim ID and run urgency triage.
//
// Triage runs here, not only in the conversation flow, because an LLM
// judging "is this urgent?" can answer differently on identical input.
// A keyword rule is deterministic -- and urgency drives a real SLA
// (24-48h vs 5-7 business days per the policy FAQ). The agent's own
// guess arrives as urgency_hint and may escalate to Urgent, but can
// never downgrade an Urgent to Standard.
//
// IMPORTANT: this node's output goes straight into a Google Sheets
// append using Auto-Map Input Data, so it must emit EXACTLY the ten
// columns of the Claims tab and nothing else. Anything extra would try
// to become a column.
// ---------------------------------------------------------------

const d = $json;

// CLM- plus the last 6 digits of the epoch clock: monotonic, collision
// free at demo volumes, and short enough to read aloud digit by digit.
const claimId = `CLM-${String(Date.now()).slice(-6)}`;

const URGENT = [
  'injur', 'hurt', 'wound', 'bleed', 'blood', 'broken bone', 'fracture',
  'hospital', 'ambulance', 'emergency', 'icu', 'surgery', 'unconscious',
  'concussion', 'paramedic', 'fire', 'burn', 'smoke', 'explosion',
  'flood', 'gas leak', 'collapse', 'structural damage', 'totaled',
  'total loss', 'write-off', 'life threatening', 'life-threatening',
  'critical', 'death', 'died', 'fatal'
];

const haystack = `${d.description} ${d.incident_type}`.toLowerCase();
const matched = URGENT.some((k) => haystack.includes(k));
const urgency =
  matched || String(d.urgency_hint || '').toLowerCase() === 'urgent'
    ? 'Urgent'
    : 'Standard';

// Match the timestamp format of the provided Claims-Template.csv so the
// dashboard can parse the whole column with one format.
const n = new Date();
const p = (x) => String(x).padStart(2, '0');
const createdAt =
  `${n.getFullYear()}-${p(n.getMonth() + 1)}-${p(n.getDate())} ` +
  `${p(n.getHours())}:${p(n.getMinutes())}`;

return [{ json: {
  claim_id: claimId,
  policy_number: d.policy_number,
  holder_name: d.holder_name,
  incident_type: d.incident_type || 'Other',
  incident_date: d.incident_date,
  description: d.description,
  urgency: urgency,
  status: 'Filed',
  email: d.email,
  created_at: createdAt
}}];

// Return only what the agent needs to speak. Every extra field is one
// more thing the model can decide to read out loud to the caller.
const c = $('Generate Claim ID & Triage').first().json;

return [{ json: {
  result: c.urgency === 'Urgent' ? 'urgent' : 'standard',
  success: true,
  claim_id: c.claim_id,
  urgency: c.urgency,
  status: c.status,
  holder_name: c.holder_name,
  incident_type: c.incident_type,
  message: c.urgency === 'Urgent'
    ? `Claim ${c.claim_id} has been filed and flagged as urgent for priority review within 24 to 48 hours.`
    : `Claim ${c.claim_id} has been filed and will be reviewed within 5 to 7 business days.`
}}];

// Find the claim among the rows read from the Claims tab.
// `result: not_found` is a normal outcome, not an error -- the
// conversation flow branches on it to offer a retry or a handoff.
const asked = $('Normalize Request').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.claim_id);
const row = rows.find(
  (r) => String(r.claim_id).trim().toUpperCase() === asked.claim_id
);

if (!row) {
  return [{ json: {
    result: 'not_found', found: false, claim_id: asked.claim_id,
    message: `No claim found with ID ${asked.claim_id}.`
  }}];
}

return [{ json: {
  result: 'found', found: true,
  claim_id: row.claim_id, status: row.status,
  incident_type: row.incident_type, urgency: row.urgency,
  holder_name: row.holder_name, incident_date: row.incident_date,
  created_at: row.created_at,
  message: `Claim ${row.claim_id} for a ${row.incident_type} incident is currently ${row.status}.`
}}];
